CREATE TABLE crm_payment_images(id CHAR(36) PRIMARY KEY,lead_id VARCHAR(191) NOT NULL,entry_id CHAR(36) NOT NULL,created_by VARCHAR(191) NOT NULL,name VARCHAR(160) NOT NULL,mime VARCHAR(32) NOT NULL,bytes INT NOT NULL,sha256 CHAR(64) NOT NULL,content LONGBLOB NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),INDEX payment_image_entry(lead_id,entry_id),FOREIGN KEY(lead_id) REFERENCES portal_leads(id)) ENGINE=InnoDB;
